// A JSX runtime that marks every host element it creates, so that a test can
// tell whether it was used instead of React's own runtime.
const runtime = require('react/jsx-runtime')

function mark(type, props) {
  return typeof type === 'string' ? { ...props, 'data-custom-jsx': '' } : props
}

exports.Fragment = runtime.Fragment
exports.jsx = (type, props, key) => runtime.jsx(type, mark(type, props), key)
exports.jsxs = (type, props, key) => runtime.jsxs(type, mark(type, props), key)
